301|  public saveTimerSession(session: TimerSessionRecord): TimerSessionRecord[] {
302|    const existing = this.getTimerSessions();
303|    const updated = [session, ...existing];
304|    setItem(KEYS.TIMERS, updated);
305|
306|    // Also update today's logged deep work mins on profile
307|    const profile = this.getProfile();
308|    const today = new Date().toISOString().split('T')[0];
309|    const todayMins = updated
310|      .filter(s => s.completedAt.startsWith(today))
311|      .reduce((sum, s) => sum + s.durationMins, 0);
312|
313|    profile.todayLoggedDeepWorkMins = todayMins;
314|    if (todayMins >= 540) { // 9 Hours
315|      profile.isWarRoomLocked = false;
316|    }
317|    this.saveProfile(profile);
318|
319|    return updated;
