336|    const backup = {
337|      version: '1.0',
338|      exportedAt: new Date().toISOString(),
339|      profile: this.getProfile(),
340|      mocks: this.getMocks(),
341|      errors: this.getErrors(),
342|      tasks: this.getTasks(),
