347|      challenges: this.getChallenges(),
348|    };
349|    return JSON.stringify(backup, null, 2);
350|  }
351|
352|  public importBackupJSON(jsonStr: string): boolean {
353|    try {
354|      const data = JSON.parse(jsonStr);
355|      if (!data.profile || !data.mocks || !data.errors) {
356|        throw new Error('Invalid backup schema');
357|      }
358|      setItem(KEYS.PROFILE, data.profile);
359|      setItem(KEYS.MOCKS, data.mocks);
360|      setItem(KEYS.ERRORS, data.errors);
361|      setItem(KEYS.TASKS, data.tasks || []);
362|      setItem(KEYS.CA, data.ca || []);
363|      setItem(KEYS.DRILLS, data.drills || []);
364|      setItem(KEYS.MATERIALS, data.materials || SEED_MATERIALS);
365|      setItem(KEYS.TIMERS, data.timers || SEED_TIMERS);
366|      setItem(KEYS.CHALLENGES, data.challenges || []);
367|      return true;
368|    } catch (err) {
369|      console.error('Failed to restore backup:', err);
370|      return false;
371|    }
372|  }
373|
374|  public resetToSeedData(): void {
375|    setItem(KEYS.PROFILE, INITIAL_PROFILE);
376|    setItem(KEYS.MOCKS, SEED_MOCKS);
377|    setItem(KEYS.ERRORS, SEED_ERRORS);
378|    setItem(KEYS.TASKS, []);
379|    setItem(KEYS.CA, []);
380|    setItem(KEYS.DRILLS, []);
381|    setItem(KEYS.MATERIALS, []);
382|    setItem(KEYS.TIMERS, SEED_TIMERS);
383|    setItem(KEYS.CHALLENGES, []);
384|  }
385|}
