{"content": "1|/**
2| * IBPS PO COMMAND CENTER - Core Domain Types
3| */
4|
5|export type ExamType = 
6|  | 'IBPS PO'
7|  | 'IBPS Clerk'
8|  | 'IBPS SO'
9|  | 'RRB PO'
10|  | 'RRB Clerk'
11|  | 'SBI PO'
12|  | 'SBI Clerk'
13|  | 'RBI Assistant';
14|
15|export type ExamStage = 'Prelims' | 'Mains';
16|
17|export type SubjectCategory = 'Quant' | 'Reasoning' | 'English' | 'General Awareness' | 'Computer Aptitude';
18|
19|export type ErrorType = 
20|  | 'Concept Slip'
21|  | 'Calculation Mistake'
22|  | 'Time Pressure Rush'
23|  | 'Misread Question'
24|  | 'Guessed / Unsure'
25|  | 'Formula Forgot'
26|  | 'Silly Error';
27|
28|export type TaskPriority = 'P0 - Critical' | 'P1 - High' | 'P2 - Medium' | 'P3 - Low';
29|export type TaskStatus = 'Todo' | 'In Progress' | 'Done' | 'Skipped';
30|
31|// Mock Test Logger Data Types
32|export interface SectionalScore {
33|  subject: SubjectCategory;
34|  totalQuestions: number;
35|  attempted: number;
36|  correct: number;
37|  wrong: number;
38|  score: number;
39|  cutoff: number;
40|  timeSpentMins: number;
41|  accuracy: number; // percentage
42|  weakTopics: string[];
43|}
44|
45|export interface MockTestRecord {
46|  id: string;
47|  exam: ExamType;
48|  stage: ExamStage;
49|  testSeriesProvider: string; // e.g. Testbook, Oliveboard, PracticeMock, Smartkeeda
50|  mockTitle: string; // e.g. IBPS PO Prelims Mock #14
