72|  options?: string[];
73|  correctAnswer: string;
74|  userAnswer: string;
75|  errorType: ErrorType;
76|  solutionExplanation: string;
77|  keyFormulaOrConcept: string;
78|  shortcutTrick?: string;
79|  masteryLevel: number; // 0 to 5 stars
80|  
81|  // SRS (Spaced Repetition System) fields
82|  intervalDays: number; // SM-2 interval
83|  repetitions: number;
84|  easeFactor: number; // SM-2 ease factor default 2.5
85|  nextReviewDate: string; // YYYY-MM-DD
86|  lastReviewedDate?: string;
87|  
88|  tags: string[];
89|  createdAt: number;
