{"content":"/**
 * Daily Question Generator - 300 Questions per Day
 * 100 English + 100 Quantitative + 100 Reasoning
 * Integrated with IBPS PO Command Center
 */

import { QuestionItem, SubjectCategory } from '../types';
import { generateQuestionByIndex, getTotalQuestionBankCount } from '../services/questionBank';
import { db } from '../services/db';
import { getISTTodayString } from '../utils/timeUtils';

export interface DailyQuestionSet {
  date: string; // YYYY-MM-DD
  english: QuestionItem[];
  quantitative: QuestionItem[];
  reasoning: QuestionItem[];
  gc: QuestionItem[];
  overall: QuestionItem[];
  totalCount: number;
}

export interface DailyPerformance {
  date: string;
  questionsAttempted: number;
  correctAnswers: number;
  accuracy: number;
  timeSpent: number; // minutes
  weakTopics: string[];
  improvementAreas: string[];
}

export interface WeaknessAnalysis {
  topic: string;
  attempted: number;
  correct: number;
  accuracy: number;
  needsImprovement: boolean;
  suggestedActions: string[];
}

/**
 * Generate 300 questions for the day (100 per subject)
 * Each subject gets 100 questions from the procedural generator
 */
export function generateDailyQuestions(date: string = getISTTodayString()): DailyQuestionSet {
  const totalAvailable = getTotalQuestionBankCount();

  // Calculate base index for today
  const dayNumber = new Date(date.replace(/-/g, '')).getDate();
  const baseIndex = (dayNumber * 300) % totalAvailable;

  // Generate 100 questions per subject
  const english: QuestionItem[] = [];
  const quantitative: QuestionItem[] = [];
  const reasoning: QuestionItem[] = [];
  const gc: QuestionItem[] = [];

  for (let i = 0; i < 100; i++) {
    const engIdx = (baseIndex + i * 4 + 2) % totalAvailable; // English starts at index 2
    const quantIdx = (baseIndex + i * 4) % totalAvailable;   // Quant starts at index 0
    const reasIdx = (baseIndex + i * 4 + 1) % totalAvailable; // Reasoning starts at 1
    const gcIdx = (baseIndex + i * 4 + 3) % totalAvailable;   // GC starts at 3

    english.push(generateQuestionByIndex(engIdx));
    quantitative.push(generateQuestionByIndex(quantIdx));
    reasoning.push(generateQuestionByIndex(reasIdx));
    gc.push(generateQuestionByIndex(gcIdx));
  }

  const overall = [...english, ...quantitative, ...reasoning, ...gc];

  return {
    date,
    english,
    quantitative,
    reasoning,
    gc,
    overall,
    totalCount: overall.length
  };
}

/**
 * Analyze weak areas from completed daily test
 */
export function analyzeWeaknesses(dailyPerformance: DailyPerformance): WeaknessAnalysis[] {
  const profile = db.getProfile();
  const errors = db.getErrors();
  const mocks = db.getMocks();

  const analyses: WeaknessAnalysis[] = [];

  // Topic-wise analysis
  const topicStats = new Map<string, { attempted: number; correct: number }>();

  // Analyze recent errors
  errors.slice(0, 50).forEach(error => {
    const topic = error.topic;
    const stats = topicStats.get(topic) || { attempted: 0, correct: 0 };
    stats.attempted += 1;
    // Errors count as incorrect attempts
    topicStats.set(topic, stats);
  });

  // Analyze recent mock tests
  const recentMocks = mocks.slice(0, 3);
  recentMocks.forEach(mock => {
    mock.sections.forEach(section => {
      const stats = topicStats.get(section.subject) || { attempted: 0, correct: 0 };
      stats.attempted += section.totalQuestions - section.wrong;
      stats.correct += section.correct;
      topicStats.set(section.subject, stats);
    });
  });

  // Generate improvement report for each topic
  Array.from(topicStats.entries()).forEach(([topic, stats]) => {
    const accuracy = stats.attempted > 0 ? (stats.correct / stats.attempted) * 100 : 0;
    const needsImprovement = accuracy < 70 || stats.attempted < 5;

    const suggestions: string[] = [];
    if (accuracy < 60) {
      suggestions.push(`Practice intensive drills on ${topic}`);
    }
    if (accuracy < 70) {
      suggestions.push(`Review NCERT/Naveen books for ${topic}`);
    }
    if (stats.attempted < 10) {
      suggestions.push(`Attempt more questions from ${topic}`);
    }
    if (topic.includes('Reasoning') || topic.includes('Puzzle')) {
      suggestions.push(`Focus on pattern recognition for ${topic}`);
    }
    if (topic.includes('Quant') || topic.includes('Arithmetic')) {
      suggestions.push(`Memorize shortcut formulae for ${topic}`);
    }

    analyses.push({
      topic,
      attempted: stats.attempted,
      correct: stats.correct,
      accuracy,
      needsImprovement,
      suggestedActions: suggestions
    });
  });

  return analyses.sort((a, b) => a.accuracy - b.accuracy);
}

/**
 * Get recommended improvement plan based on weakness analysis
 */
export function getImprovementPlan(weaknessAnalysis: WeaknessAnalysis[]): string[] {
  const plans: string[] = [];

  // High priority improvements
  const critical = weaknessAnalysis.filter(w => w.accuracy < 50);
  if (critical.length > 0) {
    plans.push(`🔴 CRITICAL: Focus intensively on ${critical.map(c => c.topic).join(', ')}`);
    plans.push(`   → Dedicate 2-3 hours daily to these topics`);
  }

  // Medium priority
  const moderate = weaknessAnalysis.filter(w => w.accuracy >= 50 && w.accuracy < 70);
  if (moderate.length > 0) {
    plans.push(`🟡 MEDIUM: Strengthen ${moderate.map(m => m.topic).join(', ')}`);
    plans.push(`   → Allocate 1 hour daily for targeted practice`);
  }

  // Light review
  const light = weaknessAnalysis.filter(w => w.accuracy >= 70 && w.accuracy < 80);
  if (light.length > 0) {
    plans.push(`🟢 LOW: Quick revision of ${light.map(l => l.topic).join(', ')}`);
    plans.push(`   → 30 minutes review session`);
  }

  // Daily execution plan
  plans.push('\n📋 TODAY\'S ACTION PLAN:');
  plans.push('   Morning (2 hrs): English Error Detection + RC');
  plans.push('   Afternoon (2 hrs): Quant Speed-Distance + Profit-Loss');
  plans.push('   Evening (1.5 hrs): Reasoning Puzzles + Arrangements');
  plans.push('   Before Bed (30 mins): Quick Theory Revise');

  return plans;
}

/**
 * Generate YouTube video recommendations for weak topics
 */
export function getVideoRecommendations(weakTopics: string[]): string[] {
  const recommendations: string[] = [];

  const videoMap: Record<string, string[]> = {
    'arithmetic': [
      'https://www.youtube.com/watch?v=example1', // Speed Distance Time
      'https://www.youtube.com/watch?v=example2', // Profit Loss Tricks
      'https://www.youtube.com/watch?v=example3'  // Number Series
    ],
    'reasoning': [
      'https://www.youtube.com/watch?v=example4', // Seating Arrangement
      'https://www.youtube.com/watch?v=example5', // Puzzles
      'https://www.youtube.com/watch?v=example6'  // Syllogism
    ],
    'english': [
      'https://www.youtube.com/watch?v=example7', // Error Detection
      'https://www.youtube.com/watch?v=example8', // RC Strategy
      'https://www.youtube.com/watch?v=example9'  // Para Jumbles
    ]
  };

  weakTopics.forEach(topic => {
    const topicLower = topic.toLowerCase();
    if (videoMap[topicLower]) {
      recommendations.push(...videoMap[topicLower]);
    }
  });

  return recommendations;
}

/**
 * Auto-suggest improvements for weak areas
 */
export function getAutoSuggestions(weaknessAnalysis: WeaknessAnalysis[]): string[] {
  const suggestions: string[] = [];

  // Find the weakest topic
  const weakest = weaknessAnalysis[0];
  if (weakest && weakest.needsImprovement) {
    suggestions.push(`📚 DAILY RECOMMENDATION: Start with ${weakest.topic}`);
    suggestions.push(`   Follow video series: "IBPS PO ${weakest.topic} by Adda247"`);
    suggestions.push(`   Practice 20 questions daily with timer`);
  }

  // Section-specific suggestions
  if (weaknessAnalysis.find(w => w.topic.includes('English'))) {
    suggestions.push('📖 ENGLISH: Practice 1 RC passage daily with 12 questions');
    suggestions.push('   Focus: Tone identification, inference-based questions');
  }

  if (weaknessAnalysis.find(w => w.topic.includes('Quant'))) {
    suggestions.push('🔢 QUANT: Master speed formulas first');
    suggestions.push('   Priority: Speed-Distance-Time, Profit-Loss, Number Series');
  }

  if (weaknessAnalysis.find(w => w.topic.includes('Reasoning'))) {
    suggestions.push('🧩 REASONING: Start with circular seating');
    suggestions.push('   Practice: 15 puzzles daily with 3-minute limit');
  }

  return suggestions;
