{"content":"/**
 * IBPS PO Daily Question System
 * Generates 300 questions daily: 100 English + 100 Quant + 100 Reasoning
 * Provides weakness analysis and improvement recommendations
 */

import { QuestionItem } from '../types';
import { QuestionChunkResponse, getQuestionByIndex } from '../services/questionBank';
import { db } from '../services/db';
import { getISTTodayString } from '../utils/timeUtils';

export interface DailyQuestionBatch {
  date: string; // YYYY-MM-DD
  english: QuestionItem[];
  quantitative: QuestionItem[];
  reasoning: QuestionItem[];
  total: number;
  countPerSubject: number;
}

export interface WeaknessReport {
  topic: string;
  accuracy: number;
  attempted: number;
  correct: number;
  improvementNeeded: boolean;
  suggestedActions: string[];
}

export interface DailyImprovementPlan {
  weakTopics: string[];
  videoRecommendations: string[];
  actionPlan: string[];
  weakTopicsAnalysis: WeaknessReport[];
}

/**
 * Generate 300 daily practice questions (100 each: English, Quant, Reasoning)
 * Uses the existing procedural question bank generator
 */
export function generateDailyQuestionBatch(date: string = getISTTodayString()): DailyQuestionBatch {
  const countPerSubject = 100;
  const english: QuestionItem[] = [];
  const quantitative: QuestionItem[] = [];
  const reasoning: QuestionItem[] = [];

  // Generate 100 questions per subject
  // Index pattern: Quant=0, Reasoning=1, English=2, GA=3
  const dayOffset = new Date(date).getDate() * 300;

  for (let i = 0; i < countPerSubject; i++) {
    // Quant questions: indices 0, 4, 8, 12...
    const quantIdx = ((dayOffset + i * 4) % 50000);
    quantitative.push(getQuestionByIndex(quantIdx));

    // Reasoning questions: indices 1, 5, 9, 13...
    const reasIdx = ((dayOffset + i * 4 + 1) % 50000);
    reasoning.push(getQuestionByIndex(reasIdx));

    // English questions: indices 2, 6, 10, 14...
    const engIdx = ((dayOffset + i * 4 + 2) % 50000);
    english.push(getQuestionByIndex(engIdx));
  }

  return {
    date,
    english,
    quantitative,
    reasoning,
    total: english.length + quantitative.length + reasoning.length,
    countPerSubject
  };
}

/**
 * Analyze weak areas from user's performance
 */
export function analyzePerformance(): WeaknessReport[] {
  const errors = db.getErrors();
  const mocks = db.getMocks();

  const topicStats = new Map<string, { attempted: number; correct: number }>();

  // Analyze errors (incorrect attempts)
  errors.forEach(error => {
    const stats = topicStats.get(error.topic) || { attempted: 0, correct: 0 };
    stats.attempted += 1;
    topicStats.set(error.topic, stats);
  });

  // Analyze mock tests
  mocks.slice(0, 3).forEach(mock => {
    mock.sections.forEach(section => {
      const stats = topicStats.get(section.subject) || { attempted: 0, correct: 0 };
      stats.attempted += section.wrong;
      stats.correct += section.correct;
      topicStats.set(section.subject, stats);
    });
  });

  // Generate reports
  const reports: WeaknessReport[] = [];

  topicStats.forEach((stats, topic) => {
    const accuracy = stats.attempted > 0 ? (stats.correct / stats.attempted) * 100 : 0;
    const needsImprovement = accuracy < 70 || stats.attempted < 10;

    const suggestions: string[] = [];
    if (accuracy < 50) {
      suggestions.push(`Intensive practice needed`);
    }
    if (accuracy < 70) {
      suggestions.push(`Targeted revision required`);
    }
    if (stats.attempted < 15) {
      suggestions.push(`More attempts needed`);
    }

    reports.push({
      topic,
      accuracy: Math.round(accuracy * 100) / 100,
      attempted: stats.attempted,
      correct: stats.correct,
      improvementNeeded: needsImprovement,
      suggestedActions: suggestions
    });
  });

  return reports.sort((a, b) => a.accuracy - b.accuracy);
}

/**
 * Generate improvement plan and recommendations
 */
export function generateImprovementPlan(): DailyImprovementPlan {
  const weaknessReports = analyzePerformance();
  const weakTopics = weaknessReports
    .filter(r => r.improvementNeeded)
    .map(r => r.topic);

  // Video recommendations based on weak topics
  const videoMap: Record<string, string[]> = {
    'arithmetic': [
      'Speed Distance Time Tricks: https://youtu.be/watch?v=sample1',
      'Profit Loss Shortcuts: https://youtu.be/watch?v=sample2',
      'Number Series Patterns: https://youtu.be/watch?v=sample3'
    ],
    'seating_arrangement': [
      'Circular Arrangement Strategy: https://youtu.be/watch?v=sample4',
      'Puzzle Solving Tips: https://youtu.be/watch?v=sample5'
    ],
    'error_detection': [
      'Grammar Mistakes Guide: https://youtu.be/watch?v=sample6',
      'RC Strategies: https://youtu.be/watch?v=sample7'
    ]
  };

  const videos: string[] = [];
  weakTopics.forEach(topic => {
    const key = topic.toLowerCase().replace(/ /g, '_');
    if (videoMap[key]) {
      videos.push(...videoMap[key]);
    }
  });

  // Action plan
  const actions = [
    `📅 TODAY: Dedicate 2 hours to ${weakTopics[0] || 'weak topics'}`,
    `⏱️ Use 3-minute timer per question in practice`,
    `📚 Review theory before attempting questions`,
    `🎯 Focus on accuracy over speed initially`,
    `📝 Maintain error notebook for mistakes`
  ];

  return {
    weakTopics,
    videoRecommendations: videos.slice(0, 5),
    actionPlan: actions,
    weakTopicsAnalysis: weaknessReports.slice(0, 5)
  };
}

/**
 * Export daily batch to CSV format
 */
export function exportToCSV(batch: DailyQuestionBatch): string {
  const headers = ['ID', 'Subject', 'Topic', 'Question', 'Option A', 'Option B', 'Option C', 'Option D', 'Answer', 'Time'];
  const rows = [headers.join(',')];

  const allQuestions = [
    ...batch.english.map(q => ({ ...q, subject: 'English' })),
    ...batch.quantitative.map(q => ({ ...q, subject: 'Quant' })),
    ...batch.reasoning.map(q => ({ ...q, subject: 'Reasoning' }))
  ];

  allQuestions.forEach(q => {
    const row = [
      q.id,
      q.subject,
      q.topic,
      `"${q.questionText.replace(/"/g, '""')}"`,
      `"${q.options[0]}"`,
      `"${q.options[1]}"`,
      `"${q.options[2]}"`,
      `"${q.options[3]}"`,
      q.correctAnswer.toString(),
      q.expectedTimeSecs.toString()
    ];
    rows.push(row.join(','));
  });

  return rows.join('\n');
}

