import React, { useState, useEffect } from 'react';
import { generateDailyQuestionBatch, generateImprovementPlan, DailyQuestionBatch, DailyImprovementPlan } from '../../services/dailyQuestionBatch';
import { getISTTodayString } from '../../utils/timeUtils';

interface DailyPracticeDashboardProps {
  onComplete: (performance: { accuracy: number; timeSpent: number }) => void;
}

export const DailyPracticeDashboard: React.FC<DailyPracticeDashboardProps> = ({ onComplete }) => {
  const [batch, setBatch] = useState<DailyQuestionBatch | null>(null);
  const [improvement, setImprovement] = useState<DailyImprovementPlan | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const today = getISTTodayString();
    const dailyBatch = generateDailyQuestionBatch(today);
    setBatch(dailyBatch);

    const plan = generateImprovementPlan();
    setImprovement(plan);
  }, []);

  if (!batch || !improvement) {
    return (
      <div className="p-6">
        <h2 className="text-2xl font-bold mb-4">Daily Practice - 300 Questions</h2>
        <div className="text-center py-10">
          <p className="text-gray-400">Loading your daily question batch...</p>
        </div>
      </div>
    );
  }

  const allQuestions = [
    ...batch.english.map(q => ({ ...q, subject: 'English' })),
    ...batch.quantitative.map(q => ({ ...q, subject: 'Quant' })),
    ...batch.reasoning.map(q => ({ ...q, subject: 'Reasoning' }))
  ];

  const currentQ = allQuestions[currentIndex];
  const currentSubject = currentIndex < 100 ? 'English' : currentIndex < 200 ? 'Quant' : 'Reasoning';

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-bold">Daily Practice Session</h2>
        <span className="text-gray-400">
          {currentIndex + 1} / {allQuestions.length}
        </span>
      </div>

      {/* Subject Distribution */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-blue-900/20 p-4 rounded">
          <h3 className="font-semibold">English</h3>
          <p className="text-2xl">100</p>
        </div>
        <div className="bg-green-900/20 p-4 rounded">
          <h3 className="font-semibold">Quantitative</h3>
          <p className="text-2xl">100</p>
        </div>
        <div className="bg-purple-900/20 p-4 rounded">
          <h3 className="font-semibold">Reasoning</h3>
          <p className="text-2xl">100</p>
        </div>
      </div>

      {/* Weak Topics */}
      {improvement.weakTopics.length > 0 && (
        <div className="bg-red-900/20 p-4 rounded mb-6">
          <h3 className="font-semibold mb-2">Improvement Needed:</h3>
          <ul className="list-disc list-inside text-red-200">
            {improvement.weakTopics.map(t => <li key={t}>{t}</li>)}
          </ul>
        </div>
      )}

      {/* Question Display */}
      <div className="bg-gray-800/50 rounded-lg p-6 mb-6">
        <div className="flex justify-between items-center mb-4">
          <span className="text-xs bg-blue-500/20 px-2 py-1 rounded">
            {currentSubject} - {currentQ.topic}
          </span>
          <span className="text-gray-400 text-sm">{currentQ.difficulty}</span>
        </div>

        <h3 className="text-lg mb-4" 
          dangerouslySetInnerHTML={{ __html: currentQ.questionText }} />

        <div className="grid grid-cols-2 gap-3">
          {currentQ.options.map((opt, idx) => (
            <button
              key={idx}
              onClick={() => {
                const newAnswers = { ...answers, [currentQ.id]: String(idx) };
                setAnswers(newAnswers);
                if (currentIndex < allQuestions.length - 1) {
                  setCurrentIndex(currentIndex + 1);
                } else {
                  const correct = Object.values(newAnswers).filter(a => a === String(currentQ.correctAnswer)).length;
                  onComplete({
                    accuracy: (correct / allQuestions.length) * 100,
                    timeSpent: 0 // Would track actual time
                  });
                }
              }}
              className="p-3 bg-gray-700/30 rounded hover:bg-gray-600/50 text-left"
            >
              <span className="font-bold mr-2">{['A', 'B', 'C', 'D', 'E'][idx]}</span>
              {opt}
            </button>
          ))}
        </div>
      </div>

      {/* Action Plan */}
      <div className="bg-gray-800/50 rounded-lg p-4">
        <h3 className="font-semibold mb-3">Today's Action Plan</h3>
        <ol className="space-y-2">
          {improvement.actionPlan.slice(0, 3).map((action, idx) => (
            <li key={idx} className="text-sm">{action}</li>
          ))}
        </ol>
      </div>
    </div>
  );
};

